// ?AddOutput@Debug@@AAEXPBDI@Z
// partial score=0.5985 date=2026-09-28
// cl: /DNDEBUG /MD /EHs-c- /Oy-
// BFME Debug::AddOutput(const char *, unsigned) at 0x0088A8F0 (675 bytes).
// Zero Hour twin: debug_debug.cpp Debug::AddOutput.
//
// BFME's Debug is a later revision than the vendored Zero Hour header: the
// I/O buffers are seven 16-byte records at +0x9C84, curType is the int at
// +0x9CF4, the enum has no Other member (MAX == 7, Log == 1) and the
// timestamp flag is the byte at +0x9E6E.  Those offsets are the whole reason
// this TU carries its own ABI view of the class instead of including
// debug_debug.h; the sibling Debug TUs (Debug_OperatorString_0088C020.cpp,
// Debug_ExecCommand_0088ABA0.cpp) do the same.
//
// Relative to the Zero Hour source BFME also rewrote the append step: it
// counts '\n' first, grows by (newlines + len + 1024) rather than (len + 1024),
// and only falls back to memcpy when the chunk had no newline at all.

#include <windows.h>
#include <string.h>

// The enum values retail compares against: Log == 1, MAX == 7.
class DebugIOInterface
{
public:
    enum StringType
    {
        Assert = 0,
        Log = 1,
        Check = 2,
        Crash = 3,
        Exception = 4,
        CmdReply = 5,
        StructuredCmdReply = 6,
        MAX = 7
    };
};

// 0x0088A230, the Debug::FlushOutput(bool) this body reaches through.
struct BfmeThingQO
{
    void bfmeFlushQO(int defaultLog);
};

// 0x0088EB90, debug_internal.cpp.
void *DebugReAllocMemory(void *mem, unsigned size);

class Debug
{
    struct IOBuffer
    {
        char *buffer;
        unsigned used;
        unsigned alloc;
        bool lastWasCR;
    };

    unsigned char m_beforeIOBuffer[0x9C84];
    IOBuffer ioBuffer[DebugIOInterface::MAX];   // +0x9C84
    DebugIOInterface::StringType curType;       // +0x9CF4
    unsigned char m_beforeTimeStamp[0x9E6E - 0x9CF8];
    bool timeStamp;                             // +0x9E6E

    void AddOutput(const char *str, unsigned len);
};

// ?AddOutput@Debug@@AAEXPBDI@Z
void Debug::AddOutput(const char *str, unsigned remainingLen)
{
    // bail out if no valid destination type
    if (curType==DebugIOInterface::StringType::MAX)
        return;

    while (remainingLen)
    {
        unsigned len;
        if (timeStamp)
        {
            // add timestamp now?
            if (ioBuffer[curType].lastWasCR)
            {
                SYSTEMTIME systime;
                GetLocalTime(&systime);

                char ts[40];
                wsprintf(ts,"[%02i:%02i.%02i.%03i] ",systime.wHour,systime.wMinute,
                         systime.wSecond,systime.wMilliseconds);

                unsigned tsLen=strlen(ts);
                memcpy(ioBuffer[curType].buffer+ioBuffer[curType].used,ts,tsLen+1);
                ioBuffer[curType].used+=tsLen;
            }

            // search for next '\n'
            const char *p=str;
            const char *end=str+remainingLen;
            while (p!=end)
            {
                if (*p++=='\n')
                    break;
            }
            len=p-str;
        }
        else
            len=remainingLen;

        // count the newlines in this chunk, each one grows the output by a CR
        unsigned newlines=0;
        for (unsigned i=0;i<len;i++)
            if (str[i]=='\n')
                newlines++;

        if (ioBuffer[curType].used+newlines+len+64>=ioBuffer[curType].alloc)
        {
            // no, must grow buffer
            ioBuffer[curType].alloc+=newlines+len+1024;
            ioBuffer[curType].buffer=(char *)
                DebugReAllocMemory(ioBuffer[curType].buffer,ioBuffer[curType].alloc);
        }

        if (newlines)
        {
            // expand every '\n' into a CR/LF pair
            char *dest=ioBuffer[curType].buffer+ioBuffer[curType].used;
            const char *src=str;
            unsigned n=len;
            while (n)
            {
                *dest++=*src++;
                if (dest[-1]=='\n')
                {
                    dest[-1]='\r';
                    *dest++='\n';
                }
                --n;
            }
            *dest=0;
            ioBuffer[curType].used+=newlines+len;
        }
        else
        {
            // add to buffer (with NUL)
            memcpy(ioBuffer[curType].buffer+ioBuffer[curType].used,str,len+1);
            ioBuffer[curType].used+=len;
        }

        // last char CR?
        ioBuffer[curType].lastWasCR=str[len-1]=='\n';
        str+=len;
        remainingLen-=len;

        // are we writing a log string?
        if (curType==DebugIOInterface::Log&&ioBuffer[curType].lastWasCR)
        {
            // yes, flush out now
            ((BfmeThingQO *)this)->bfmeFlushQO(1);
            curType=DebugIOInterface::Log;
        }
    }
}
